55	
56	@RestController
57	@CrossOrigin(exposedHeaders = "errors, content-type")
58	@RequestMapping("/api")
59	public class OwnerRestControllerV1 implements OwnersApi {
60	
61	    /**
62	     * Syntactic check for an email address: a non-empty local part, a single {@code @}, and a
63	     * domain containing at least one dot, with no whitespace in any part.
64	     */
65	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
