85	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
86	    @Override
87	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
88	        Collection<Owner> owners;
89	        if (lastName != null) {
90	            owners = this.clinicService.findOwnerByLastName(lastName);
91	        } else {
92	            owners = this.clinicService.findAllOwners();
93	        }
94	        if (owners.isEmpty()) {
95	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
96	        }
97	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
103	        Owner owner = this.clinicService.findOwnerById(ownerId);
104	        if (owner == null) {
105	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
106	        }
107	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
108	    }
109	
110	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
111	    @Override
112	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
113	        validateRequiredFields(ownerFieldsDto);
114	        HttpHeaders headers = new HttpHeaders();
115	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
116	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
117	        rejectDuplicateTelephone(telephone);
118	        owner.setTelephone(telephone);
119	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
120	        this.clinicService.saveOwner(owner);
121	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
122	        headers.setLocation(UriComponentsBuilder.newInstance()
123	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
124	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
125	    }
126	
127	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
128	    @Override
129	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
130	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
131	        if (currentOwner == null) {
132	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
133	        }
134	        currentOwner.setAddress(ownerFieldsDto.getAddress());
135	        currentOwner.setCity(ownerFieldsDto.getCity());
136	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
137	        currentOwner.setLastName(ownerFieldsDto.getLastName());
138	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
139	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
140	        this.clinicService.saveOwner(currentOwner);
141	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
142	    }
